// PoC cloud flow definitions (Logic Apps workflow definition language).
// All flows share ONE trigger input: `payload` (a JSON string). The Code App
// sends e.g. {"correlationId":"…","delaySeconds":60,"label":"poc"}.
// Keeping a single text input means the trigger schema never changes, so the
// services generated by `pa app add flow` never go stale when we edit flow internals.

export function buildFlows(prefix = 'pa') {
  const P = prefix;
  const ENTITY_SET = `${P}_benchmarkruns`;
  const DV = 'shared_commondataserviceforapps';
  const SP = 'shared_sharepointonline';

  // ------------------------------------------------------------------ helpers
  const dvAction = (operationId, parameters, runAfter) => ({
    type: 'OpenApiConnection',
    inputs: {
      host: { connectionName: DV, operationId, apiId: `/providers/Microsoft.PowerApps/apis/${DV}` },
      parameters,
      authentication: "@parameters('$authentication')",
    },
    runAfter,
  });

  const spHttp = (method, uri, headers, body, runAfter) => ({
    type: 'OpenApiConnection',
    inputs: {
      host: { connectionName: SP, operationId: 'HttpRequest', apiId: `/providers/Microsoft.PowerApps/apis/${SP}` },
      parameters: {
        dataset: "@outputs('Payload')?['siteUrl']",
        'parameters/method': method,
        'parameters/uri': uri,
        'parameters/headers': headers,
        ...(body !== undefined ? { 'parameters/body': body } : {}),
      },
      authentication: "@parameters('$authentication')",
    },
    runAfter,
  });

  const trigger = {
    manual: {
      type: 'Request',
      kind: 'PowerAppV2',
      inputs: {
        schema: {
          type: 'object',
          properties: {
            text: {
              title: 'payload',
              type: 'string',
              description: 'JSON payload from the Code App',
              'x-ms-dynamically-added': true,
              'x-ms-content-hint': 'TEXT',
            },
          },
          required: ['text'],
        },
      },
    },
  };

  const env = "workflow()?['tags']?['environmentName']";
  const flowName = "workflow()?['name']";
  const runName = "workflow()?['run']?['name']";

  const common = {
    Start: { type: 'Compose', inputs: '@utcNow()', runAfter: {} },
    Payload: {
      type: 'Compose',
      inputs: "@json(coalesce(triggerBody()?['text'], '{}'))",
      runAfter: { Start: ['Succeeded'] },
    },
    Links: {
      type: 'Compose',
      inputs: {
        environmentId: `@{${env}}`,
        flowId: `@{${flowName}}`,
        runId: `@{${runName}}`,
        runUrl: `@{concat('https://make.powerautomate.com/environments/', ${env}, '/flows/', ${flowName}, '/runs/', ${runName})}`,
        runUrlSolution: `@{concat('https://make.powerautomate.com/environments/', ${env}, '/solutions/~preferred/flows/', ${flowName}, '/runs/', ${runName})}`,
        editUrl: `@{concat('https://make.powerautomate.com/environments/', ${env}, '/flows/', ${flowName}, '/edit')}`,
        detailsUrl: `@{concat('https://make.powerautomate.com/environments/', ${env}, '/flows/', ${flowName}, '/details')}`,
      },
      runAfter: { Payload: ['Succeeded'] },
    },
  };

  const createRow = (scenario, variant, technique, volumeExpr) =>
    dvAction('CreateRecord', {
      entityName: ENTITY_SET,
      [`item/${P}_name`]: "@outputs('Payload')?['correlationId']",
      [`item/${P}_scenario`]: scenario,
      [`item/${P}_variant`]: variant,
      [`item/${P}_technique`]: technique,
      [`item/${P}_status`]: 'Running',
      [`item/${P}_label`]: "@{outputs('Payload')?['label']}",
      [`item/${P}_volume`]: volumeExpr,
      [`item/${P}_starttime`]: "@outputs('Start')",
      [`item/${P}_runid`]: "@outputs('Links')?['runId']",
      [`item/${P}_flowid`]: "@outputs('Links')?['flowId']",
      [`item/${P}_environmentid`]: "@outputs('Links')?['environmentId']",
      [`item/${P}_runurl`]: "@outputs('Links')?['runUrl']",
      [`item/${P}_runurlsolution`]: "@outputs('Links')?['runUrlSolution']",
      [`item/${P}_editurl`]: "@outputs('Links')?['editUrl']",
      // Dump workflow() so we can see every tag the platform exposes (e.g. xrmWorkflowId)
      [`item/${P}_details`]: '@{string(workflow())}',
    }, { Links: ['Succeeded'] });

  const durationMs = "@div(sub(ticks(utcNow()), ticks(outputs('Start'))), 10000)";

  const updateRow = (extra, runAfter) =>
    dvAction('UpdateRecord', {
      entityName: ENTITY_SET,
      recordId: `@outputs('Create_run_row')?['body/${P}_benchmarkrunid']`,
      [`item/${P}_status`]: 'Succeeded',
      [`item/${P}_endtime`]: '@utcNow()',
      [`item/${P}_durationms`]: durationMs,
      ...extra,
    }, runAfter);

  const respond = (runAfter) => ({
    type: 'Response',
    kind: 'PowerApp',
    inputs: {
      statusCode: 200,
      body: {
        runid: "@{outputs('Links')?['runId']}",
        runurl: "@{outputs('Links')?['runUrl']}",
        respondedat: '@{utcNow()}',
      },
      schema: {
        type: 'object',
        properties: {
          runid: { title: 'runId', type: 'string', 'x-ms-dynamically-added': true },
          runurl: { title: 'runUrl', type: 'string', 'x-ms-dynamically-added': true },
          respondedat: { title: 'respondedAt', type: 'string', 'x-ms-dynamically-added': true },
        },
      },
    },
    runAfter,
  });

  const delay = (runAfter) => ({
    type: 'Wait',
    inputs: { interval: { count: "@max(1, int(coalesce(outputs('Payload')?['delaySeconds'], 1)))", unit: 'Second' } },
    runAfter,
  });

  const delayVolume = "@int(coalesce(outputs('Payload')?['delaySeconds'], 0))";

  // ------------------------------------------------------------------ flows
  const flows = [];

  // #4 respond early: does the flow keep running after "Respond to a Power App or flow"?
  flows.push({
    name: 'PocRespondEarly',
    description: 'PoC: responds to the Code App immediately, then waits delaySeconds and completes the telemetry row.',
    connections: [DV],
    actions: {
      ...common,
      Create_run_row: createRow('POC', 'RespondEarly', 'Respond early, then keep working', delayVolume),
      Respond_to_app: respond({ Create_run_row: ['Succeeded'] }),
      Delay: delay({ Respond_to_app: ['Succeeded'] }),
      Update_run_row: updateRow({}, { Delay: ['Succeeded'] }),
    },
  });

  // #3 / #5b respond late: plain invoke (delay 1) and the >120 s case (delay 150)
  flows.push({
    name: 'PocRespondLate',
    description: 'PoC: waits delaySeconds, completes the telemetry row, then responds (tests the 120 s limit).',
    connections: [DV],
    actions: {
      ...common,
      Create_run_row: createRow('POC', 'RespondLate', 'Respond at the end', delayVolume),
      Delay: delay({ Create_run_row: ['Succeeded'] }),
      Update_run_row: updateRow({}, { Delay: ['Succeeded'] }),
      Respond_to_app: respond({ Update_run_row: ['Succeeded'] }),
    },
  });

  // #5a no response at all: fire-and-forget
  flows.push({
    name: 'PocNoRespond',
    description: 'PoC: no Respond action at all (fire-and-forget). Waits delaySeconds and completes the telemetry row.',
    connections: [DV],
    actions: {
      ...common,
      Create_run_row: createRow('POC', 'NoRespond', 'No response action', delayVolume),
      Delay: delay({ Create_run_row: ['Succeeded'] }),
      Update_run_row: updateRow({}, { Delay: ['Succeeded'] }),
    },
  });

  // #8 SharePoint $batch: one changeset with batchSize item creations, built without a loop
  const CRLF = "outputs('CRLF')";
  const pl = (k) => `outputs('Payload')?['${k}']`;
  const respText = "outputs('Response_text')";
  flows.push({
    name: 'PocSpBatch',
    description: 'PoC: creates batchSize SharePoint items in ONE $batch request (changeset built with Select + join). Optional bad item to test rollback.',
    connections: [DV, SP],
    actions: {
      ...common,
      Create_run_row: createRow('POC', 'SpBatch', 'SharePoint $batch (one changeset)', `@int(coalesce(${pl('batchSize')}, 100))`),
      CRLF: { type: 'Compose', inputs: "@decodeUriComponent('%0D%0A')", runAfter: { Create_run_row: ['Succeeded'] } },
      Ids: { type: 'Compose', inputs: { batch: '@{guid()}', cs: '@{guid()}' }, runAfter: { CRLF: ['Succeeded'] } },
      Get_list_entity_type: spHttp('GET',
        `_api/web/lists/getbytitle('@{${pl('listName')}}')?$select=ListItemEntityTypeFullName`,
        { Accept: 'application/json;odata=nometadata' }, undefined, { Ids: ['Succeeded'] }),
      Batch_parts: {
        type: 'Select',
        inputs: {
          from: `@range(0, int(coalesce(${pl('batchSize')}, 100)))`,
          select: `@concat('--changeset_', outputs('Ids')?['cs'], ${CRLF}, 'Content-Type: application/http', ${CRLF}, 'Content-Transfer-Encoding: binary', ${CRLF}, ${CRLF}, 'POST ', ${pl('siteUrl')}, '/_api/web/lists/getbytitle(''', ${pl('listName')}, ''')/items HTTP/1.1', ${CRLF}, 'Content-Type: application/json;odata=verbose', ${CRLF}, ${CRLF}, '{"__metadata":{"type":"', body('Get_list_entity_type')?['ListItemEntityTypeFullName'], '"},"Title":"', ${pl('correlationId')}, ' #', string(item()), '","Amount":', if(and(equals(${pl('injectBadItem')}, true), equals(item(), 0)), '"not-a-number"', string(item())), '}', ${CRLF}, ${CRLF})`,
        },
        runAfter: { Get_list_entity_type: ['Succeeded'] },
      },
      Batch_body: {
        type: 'Compose',
        inputs: `@concat('--batch_', outputs('Ids')?['batch'], ${CRLF}, 'Content-Type: multipart/mixed; boundary="changeset_', outputs('Ids')?['cs'], '"', ${CRLF}, 'Content-Transfer-Encoding: binary', ${CRLF}, ${CRLF}, join(body('Batch_parts'), ''), '--changeset_', outputs('Ids')?['cs'], '--', ${CRLF}, ${CRLF}, '--batch_', outputs('Ids')?['batch'], '--', ${CRLF})`,
        runAfter: { Batch_parts: ['Succeeded'] },
      },
      Batch_start: { type: 'Compose', inputs: '@utcNow()', runAfter: { Batch_body: ['Succeeded'] } },
      Send_batch: spHttp('POST', '_api/$batch',
        { 'Content-Type': "multipart/mixed; boundary=\"batch_@{outputs('Ids')?['batch']}\"", Accept: 'application/json;odata=verbose' },
        "@outputs('Batch_body')", { Batch_start: ['Succeeded'] }),
      Response_raw: {
        type: 'Compose',
        inputs: "@string(body('Send_batch'))",
        runAfter: { Send_batch: ['Succeeded', 'Failed'] },
      },
      Response_text: {
        type: 'Compose',
        inputs: "@if(startsWith(outputs('Response_raw'), '{\"$content'), base64ToString(coalesce(json(if(startsWith(outputs('Response_raw'), '{'), outputs('Response_raw'), '{}'))?['$content'], '')), outputs('Response_raw'))",
        runAfter: { Response_raw: ['Succeeded'] },
      },
      Update_run_row: updateRow({
        [`item/${P}_status`]: `@if(equals(sub(length(split(${respText}, 'HTTP/1.1 201')), 1), int(coalesce(${pl('batchSize')}, 100))), 'Succeeded', 'Partial')`,
        [`item/${P}_recordsprocessed`]: `@sub(length(split(${respText}, 'HTTP/1.1 201')), 1)`,
        [`item/${P}_connectorcalls`]: 2,
        [`item/${P}_loopiterations`]: 0,
        [`item/${P}_actionsestimated`]: 14,
        [`item/${P}_payloadbytes`]: "@length(outputs('Batch_body'))",
        [`item/${P}_details`]: `@{string(json(concat('{"batchHttpStatus":', string(coalesce(outputs('Send_batch')?['statusCode'], 0)), ',"batchMs":', string(div(sub(ticks(utcNow()), ticks(outputs('Batch_start'))), 10000)), ',"created201":', string(sub(length(split(${respText}, 'HTTP/1.1 201')), 1)), ',"failed4xx":', string(sub(length(split(${respText}, 'HTTP/1.1 4')), 1)), ',"failed5xx":', string(sub(length(split(${respText}, 'HTTP/1.1 5')), 1)), ',"injectBadItem":', if(equals(${pl('injectBadItem')}, true), 'true', 'false'), ',"links":', string(outputs('Links')), '}')))}`,
        [`item/${P}_error`]: `@{substring(${respText}, 0, min(length(${respText}), 4000))}`,
      }, { Response_text: ['Succeeded'] }),
      Respond_to_app: respond({ Update_run_row: ['Succeeded'] }),
    },
  });

  // ------------------------------------------------------------------ clientdata
  return flows.map((f) => ({
    name: f.name,
    description: f.description,
    clientdata: {
      properties: {
        connectionReferences: Object.fromEntries(
          f.connections.map((c) => [c, {
            runtimeSource: 'embedded',
            connection: { connectionReferenceLogicalName: c === DV ? `${P}_dataverse` : `${P}_sharepoint` },
            api: { name: c },
          }]),
        ),
        definition: {
          $schema: 'https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#',
          contentVersion: '1.0.0.0',
          parameters: {
            $connections: { defaultValue: {}, type: 'Object' },
            $authentication: { defaultValue: {}, type: 'SecureObject' },
          },
          triggers: trigger,
          actions: f.actions,
        },
        templateName: null,
      },
      schemaVersion: '1.0.0.0',
    },
  }));
}
